// @name Spotify remote
// @background #121212
// @refresh 1
// What plays on a Spotify account, and a remote for it: play and pause, skip,
// seek, shuffle, repeat, the volume, the heart (Liked Songs), the speaker it
// plays on (any Spotify Connect device of the account: a phone, a computer, a
// speaker, a frame running a Spotify Connect receiver) and a playlist to
// start.
//
// Each render asks Spotify what plays (GET /me/player) when the last answer
// is old enough: every 5 s while music plays on a screen that shows a change
// at once, every 15 s while it does not; between answers the bar moves with
// the clock. On e-paper the frame wakes when the track should end. A tap
// changes the picture at once and asks Spotify; what Spotify then says puts
// it right.
//
// spotify.ts signs in and talks to Spotify, remote.ts keeps the state and
// does what a tap asks, player.tsx and sheets.tsx draw with ui.tsx's parts.
import { authorizeUrl, positionOf, readAuth, session, settingsOf } from './spotify'
import type { Client, Settings } from './spotify'
import {
  clientOf, keep, likedOf, noteNow, playbackOf, poll, recall, setVolume, setView, shownAt, shownPlaying, shownVolume,
  seekDraft, skip, togglePlay, upcomingOf, viewOf, volumeDraft,
} from './remote'
import { dropCover, round, square, tall, wide } from './player'
import type { Ctx } from './player'
import { devicesSheet, dropThumbs, playlistsSheet, rendered } from './sheets'
import { Icon, SetupScreen, clamp, sizesOf, themeOf } from './ui'
import type { Sizes, Theme } from './ui'

// How often Spotify is asked what plays, on a screen that shows a change at
// once: while music plays, and while it does not.
const POLL_PLAYING_MS = 5000
const POLL_IDLE_MS = 15000
// On e-paper (each picture a refresh): a look when the track should end, and
// every so often while nothing plays.
const SLOW_MIN_S = 10
const SLOW_MAX_S = 300
const SLOW_IDLE_S = 120

// ---------------------------------------------------------------- keys and edge swipes

export function onEvent(app, context) {
  const p = context.payload || {}
  const view = viewOf()
  if (context.event === 'back' && view !== 'player') {
    setView('player')
    return true
  }
  if (!clientOf(app)) return false
  if (context.event === 'back') skip(app, -1)
  else if (context.event === 'forward') skip(app, 1)
  else if (context.event === 'keyDown' && !p.ctrl && !p.alt && !p.meta) {
    const key = String(p.key || '')
    if (key === 'MediaPlayPause' || key === ' ') togglePlay(app)
    else if (key === 'MediaTrackNext') skip(app, 1)
    else if (key === 'MediaTrackPrevious') skip(app, -1)
    else if (key === 'AudioVolumeUp' || key === 'AudioVolumeDown') {
      const volume = playbackOf()?.device?.volume
      if (typeof volume !== 'number') return false
      setVolume(app, volume + (key === 'AudioVolumeUp' ? 10 : -10))
    } else return false
  } else return false
  return true
}

// ---------------------------------------------------------------- the screens before the player

// How the setup screens fit the panel: `round` its circle, `tight` a short one.
type Fit = { tight?: boolean; round?: { W: number; H: number } }

function setupScreen(t: Theme, z: Sizes, fit: Fit) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="music" title="Connect Spotify"
      intro="This remote talks to Spotify through an app of your own. It takes a few minutes, once."
      steps={[
        {
          head: 'Make a Spotify app',
          text: 'On developer.spotify.com, Dashboard, Create app. Any name will do. Tick Web API, and add this Redirect URI:',
          code: 'http://127.0.0.1:8888/callback',
        },
        {
          head: 'Copy its keys into this scene',
          text: "From the app's Settings, copy the Client ID and the Client secret into this scene's settings, and save.",
        },
        {
          head: 'Sign in',
          text: 'Then this screen turns into a Sign in button.',
        },
      ]}
      note="Spotify needs Premium for remote control, and lets an app in development mode serve up to five accounts: add them under User Management." />
  )
}

function signInScreen(t: Theme, z: Sizes, fit: Fit, s: Settings, problem: string) {
  const link = authorizeUrl(s)
  return (
    <SetupScreen t={t} z={z} {...fit} icon="key" title="Sign in to Spotify" problem={problem}
      intro="Let this frame see and control what plays on your account."
      steps={[
        {
          head: 'Tap Sign in',
          text: 'Scan its QR code with your phone (the editor\'s preview opens a tab instead), log in to Spotify and press Agree.',
        },
        {
          head: 'Copy the address',
          text: 'The browser then fails to open a page. That is expected: copy its whole address, which starts with',
          code: `${s.redirectUri}?code=`,
        },
        {
          head: 'Paste it into Sign-in address',
          text: "In this scene's settings, and save. The frame signs in with it and stays signed in.",
        },
      ]}
      action={
        <a href={link}
          className={`self-center flex items-center gap-[${z.s(10)}px] h-[${z.s(52)}px] px-[${z.s(28)}px] rounded-full text-[${z.s(19)}px] font-bold ${t.primary}`}>
          <Icon name="link" size={z.s(22)} />
          <span>Sign in</span>
        </a>
      } />
  )
}
// ---------------------------------------------------------------- the scene

export function get(app, context) {
  const turned = [90, 270].includes(app.frame.rotate)
  const W = context?.imageWidth ?? (turned ? app.frame.height : app.frame.width)
  const H = context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)
  const isRound = context?.round === true
  const t = themeOf(app)
  // On a round panel the lists and the setup screens go in the square
  // inside the circle; the player uses the circle.
  const side = isRound ? Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2) : 0
  const inSquare = (ui: any) =>
    isRound ? (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${(W - side) >> 1}px] top-[${(H - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{ui}</div>
      </div>
    ) : ui
  const shape = isRound ? 'round' : W >= H * 1.25 && W >= 600 ? 'wide' : H >= W * 1.25 && H >= 600 ? 'tall' : 'square'
  const z =
    shape === 'round' ? sizesOf(Math.max(side, 360), Math.max(side, 360))
      : shape === 'wide' ? sizesOf(W, H, 800, 480)
        : shape === 'tall' ? sizesOf(W, H, 480, 800)
          : sizesOf(W, H)
  const fast = app.frame.fast ?? !app.frame.paper
  // A small screen (a 2.8" LCD) leaves out the album, what comes next and
  // the volume.
  const c: Ctx = { t, z, fast, app, compact: !isRound && Math.min(W, H) < 360 }
  // The setup screens use a round panel's whole circle, their type sized by
  // it (never under what 480 px gives); a short screen packs them tighter.
  const setup: Fit = isRound ? { round: { W, H } } : { tight: H < 400 && W < 600 }
  const zSetup = isRound ? sizesOf(clamp((Math.min(W, H) / 2 - 12) / 170, 1, 1.3) * 480, 480) : z

  const s = settingsOf(app)
  // Nothing changes on these screens until the settings do (a save renders).
  if (!s.clientId || !s.clientSecret) {
    frameos.setNextSleep(3600)
    return setupScreen(t, zSetup, setup)
  }
  const current = session(app, s)
  if (!current.signedIn) {
    dropThumbs()
    dropCover()
    for (const key of ['playback', 'liked', 'queue', 'devices', 'playlists', 'lastDevice', 'note', 'problem', 'view'])
      keep(key, null)
    frameos.setNextSleep(3600)
    return signInScreen(t, zSetup, setup, s, current.problem)
  }
  const client: Client | null = current.token ? { app, s, token: current.token } : null

  const now = Date.now()
  rendered()
  const view = viewOf()
  if (view !== 'playlists') dropThumbs()

  // Ask Spotify what plays, unless a tap's picture holds, or the answer is
  // fresh enough (sooner when the track should have ended).
  const hold = Number(recall('hold') || 0)
  let playback = playbackOf()
  const polledAt = Number(recall('polledAt') || 0)
  const ended = !!playback?.playing && !!playback.track?.ms && positionOf(playback, now) >= playback.track.ms
  const every = !fast ? 0 : ended ? 2000 : playback?.playing ? POLL_PLAYING_MS : POLL_IDLE_MS
  if (client && now >= hold && now - polledAt >= every) {
    poll(client)
    playback = playbackOf()
    // Spotify ended the sign-in during that poll: a 401 the refresh could not mend.
    const auth = readAuth(app)
    if (!auth.refresh) return signInScreen(t, zSetup, setup, s, auth.error || '')
  }
  const liked = client ? likedOf(client, playback) : null
  const upcoming = client && view === 'player' ? upcomingOf(client, playback) : []
  const problem = noteNow() || String(recall('problem') || '') || (current.problem && !client ? current.problem : '')

  // What the signals show until the next tap.
  shownPlaying.value = !!playback?.playing
  shownAt.value = playback ? positionOf(playback, now) : 0
  seekDraft.value = -1
  shownVolume.value = playback?.device?.canVolume && typeof playback.device.volume === 'number' ? playback.device.volume : -1
  volumeDraft.value = -1

  // When to look again. A fast screen renders on the scene's interval while
  // music plays (the bar moves); otherwise, and on e-paper, at the next
  // useful moment.
  const left = playback?.playing && playback.track?.ms ? playback.track.ms - positionOf(playback, now) : -1
  if (hold > now) frameos.setNextSleep((hold - now) / 1000 + 0.2)
  else if (fast && !playback?.playing) frameos.setNextSleep(POLL_IDLE_MS / 1000)
  else if (!fast) frameos.setNextSleep(left >= 0 ? clamp(left / 1000 + 2, SLOW_MIN_S, SLOW_MAX_S) : SLOW_IDLE_S)

  if (view === 'devices') return inSquare(devicesSheet(c, client, playback, problem))
  if (view === 'playlists') return inSquare(playlistsSheet(c, client, problem))
  if (shape === 'round') return round({ ...c, z: sizesOf(Math.min(W, H), Math.min(W, H)) }, W, H, playback, liked, problem)
  if (shape === 'wide') return wide(c, W, H, playback, liked, upcoming, problem)
  if (shape === 'tall') return tall(c, W, H, playback, liked, upcoming, problem)
  return square(c, W, H, playback, liked, upcoming, problem)
}

