// The remote's memory and its hands: what it keeps between renders, the
// signals a tap sets, what it asks Spotify, and what each tap does. The
// picture is player.tsx's and sheets.tsx's.
import { call, positionOf, session, settingsOf, slimDevice, slimPlayback, slimPlaylists, slimQueue } from './spotify'
import type { Client, Device, Playback, Playlist, Upcoming } from './spotify'
import { clamp } from './ui'

// After a tap the picture shows what it asked for this long before Spotify
// is asked again: a change takes Spotify a moment.
const HOLD_MS = 1500
// The list of speakers and of playlists are asked for again after this long.
const DEVICES_MS = 20000
const PLAYLISTS_MS = 10 * 60000
// A message from a tap stays this long, unless it is tapped away.
const NOTE_MS = 20000

export type View = 'player' | 'devices' | 'playlists'

// ---------------------------------------------------------------- what the app keeps

// frameos.remember: it lasts between renders, also on a board that starts
// each render with a fresh module. Module variables hold only pictures.
export const recall = (key: string): any => frameos.recall(key)
export const keep = (key: string, value: any) => frameos.remember(key, value)

export const playbackOf = (): Playback | null => recall('playback') || null
export const viewOf = (): View => recall('view') || 'player'
export const setView = (view: View) => keep('view', view)

export function note(text: string) {
  keep('note', text ? { text, at: Date.now() } : null)
}
export function noteNow(): string {
  const kept = recall('note')
  return kept && Date.now() - kept.at < NOTE_MS ? String(kept.text) : ''
}

// ---------------------------------------------------------------- signals

// What a tap changes on the play button, the bar and the volume: a handler
// that only sets these redraws the parts that read them, not the page.
export const shownPlaying = signal(false)
export const shownAt = signal(0)
export const seekDraft = signal(-1)
export const shownVolume = signal(-1)
export const volumeDraft = signal(-1)

// ---------------------------------------------------------------- talking to Spotify

// A client for one render or one tap: signed in, or null (the page says why).
export function clientOf(app): Client | null {
  const s = settingsOf(app)
  if (!s.clientId || !s.clientSecret) return null
  const current = session(app, s)
  return current.token ? { app, s, token: current.token } : null
}

// Asks Spotify what plays. The answer replaces what was kept; a failure
// keeps it and says why.
export function poll(client: Client) {
  const reply = call(client, 'GET', '/me/player?additional_types=episode')
  keep('polledAt', Date.now())
  if (reply.status === 204 || (reply.status === 200 && !reply.data)) {
    keep('playback', null)
    keep('problem', '')
    return
  }
  if (reply.status !== 200) {
    keep('problem', reply.error || `HTTP ${reply.status}`)
    return
  }
  const playback = slimPlayback(reply.data)
  keep('playback', playback)
  keep('problem', '')
  if (playback?.device?.id) keep('lastDevice', { id: playback.device.id, name: playback.device.name })
}

// Whether the track playing is in Liked Songs, asked once per track.
export function likedOf(client: Client, playback: Playback | null): boolean | null {
  const track = playback?.track
  if (!track || track.episode || !track.uri) return null
  const kept = recall('liked')
  if (kept && kept.uri === track.uri) return typeof kept.on === 'boolean' ? kept.on : null
  const reply = call(client, 'GET', `/me/library/contains?uris=${encodeURIComponent(track.uri)}`)
  // Not known (a sign-in without the library scope, say): no heart for this
  // track, and no asking again until the next one.
  const on = reply.status === 200 && Array.isArray(reply.data) ? !!reply.data[0] : null
  keep('liked', { uri: track.uri, on })
  return on
}

// What plays after this track, asked once per track.
export function upcomingOf(client: Client, playback: Playback | null): Upcoming[] {
  const track = playback?.track
  if (!track) return []
  const kept = recall('queue')
  if (kept && kept.uri === track.uri) return kept.items || []
  const reply = call(client, 'GET', '/me/player/queue')
  const items = reply.status === 200 ? slimQueue(reply.data) : []
  keep('queue', { uri: track.uri, items })
  return items
}

export function devicesOf(client: Client | null, fresh = false): Device[] {
  const kept = recall('devices')
  if (client && (fresh || !kept || Date.now() - kept.at > DEVICES_MS)) {
    const reply = call(client, 'GET', '/me/player/devices')
    if (reply.status === 200) {
      const list = (Array.isArray(reply.data?.devices) ? reply.data.devices : [])
        .map(slimDevice)
        .filter((device) => device && device.id)
        .slice(0, 20)
      keep('devices', { at: Date.now(), list })
      return list
    }
    if (reply.error) note(reply.error)
  }
  return kept?.list || []
}

export function playlistsOf(client: Client | null, fresh = false): Playlist[] {
  const kept = recall('playlists')
  if (client && (fresh || !kept || Date.now() - kept.at > PLAYLISTS_MS)) {
    const reply = call(client, 'GET', '/me/playlists?limit=50')
    if (reply.status === 200) {
      const items = slimPlaylists(reply.data)
      keep('playlists', { at: Date.now(), items })
      return items
    }
    if (reply.error) note(reply.error)
  }
  return kept?.items || []
}

// The speaker to start music on when nothing plays anywhere: the one named
// in the scene's settings, else the one music last played on.
function fallbackDevice(client: Client): string {
  const wanted = client.s.speaker.toLowerCase()
  if (wanted) {
    const named = devicesOf(client, true).find((device) => device.name.toLowerCase() === wanted)
    if (named) return named.id
  }
  const last = recall('lastDevice')
  if (last?.id) {
    const list = devicesOf(client, !wanted)
    if (list.some((device) => device.id === last.id)) return last.id
  }
  return ''
}

// Changes the kept playback at once, for the picture, and holds it a moment.
function guess(change: (playback: Playback) => void) {
  const playback = playbackOf()
  if (playback) {
    const now = Date.now()
    playback.progress = positionOf(playback, now)
    playback.at = now
    change(playback)
    keep('playback', playback)
  }
  keep('hold', Date.now() + HOLD_MS)
  // Once the hold is over, Spotify is asked at once.
  keep('polledAt', 0)
}

// Sends a command; on "nothing is playing anywhere" sends it again to the
// speaker that is there, else opens the speakers.
function command(app, method: string, path: string, body?: any, retry = true): boolean {
  const client = clientOf(app)
  if (!client) {
    note('Signed out of Spotify.')
    return false
  }
  const reply = call(client, method, path, body)
  if (reply.status >= 200 && reply.status < 300) {
    note('')
    return true
  }
  if (reply.reason === 'NO_ACTIVE_DEVICE' && retry) {
    const device = fallbackDevice(client)
    if (device) {
      const joined = path.includes('?') ? '&' : '?'
      return command(app, method, `${path}${joined}device_id=${encodeURIComponent(device)}`, body, false)
    }
    setView('devices')
    note('Nothing is playing anywhere: pick a speaker to play on.')
    keep('hold', 0)
    return false
  }
  note(reply.error || `Spotify answered HTTP ${reply.status}`)
  // The picture guessed wrong: the next render asks Spotify what is true.
  keep('hold', 0)
  keep('polledAt', 0)
  return false
}

// ---------------------------------------------------------------- what a tap does

// A tap that sets signals redraws only the parts that read them, so they
// are set once Spotify said yes. A tap that failed sets none, and the whole
// page is drawn again: its message, the speakers to pick from.
export function togglePlay(app) {
  const playing = !!playbackOf()?.playing
  if (!command(app, 'PUT', playing ? '/me/player/pause' : '/me/player/play')) return
  guess((pb) => {
    pb.playing = !playing
    // What Spotify said could not be done was about the old state.
    pb.no = { ...pb.no, pause: false, resume: false }
  })
  shownPlaying.value = !playing
}

export function skip(app, by: number) {
  if (!playbackOf()?.track) return
  if (by > 0) {
    // The queue says what comes next: show it at once.
    const next = recall('queue')?.items?.[0]
    guess((pb) => {
      if (next && pb.track) pb.track = { ...pb.track, name: next.name, by: next.by, album: '', pictures: pb.track.pictures, ms: 0 }
      pb.progress = 0
    })
  } else {
    guess((pb) => { pb.progress = 0 })
  }
  command(app, 'POST', by > 0 ? '/me/player/next' : '/me/player/previous')
}

export function seekTo(app, fraction: number) {
  const playback = playbackOf()
  if (!playback?.track?.ms) return
  const ms = Math.round(clamp(fraction, 0, 1) * playback.track.ms)
  if (!command(app, 'PUT', `/me/player/seek?position_ms=${ms}`)) return
  guess((pb) => { pb.progress = ms })
  seekDraft.value = -1
  shownAt.value = ms
}

export function setVolume(app, percent: number) {
  const value = Math.round(clamp(percent, 0, 100))
  if (!command(app, 'PUT', `/me/player/volume?volume_percent=${value}`)) return
  guess((pb) => { if (pb.device) pb.device.volume = value })
  volumeDraft.value = -1
  shownVolume.value = value
}

export function toggleShuffle(app) {
  const on = !playbackOf()?.shuffle
  guess((pb) => { pb.shuffle = on })
  command(app, 'PUT', `/me/player/shuffle?state=${on}`)
}

const REPEAT_NEXT: Record<string, string> = { off: 'context', context: 'track', track: 'off' }
export function cycleRepeat(app) {
  const next = REPEAT_NEXT[playbackOf()?.repeat || 'off'] || 'off'
  guess((pb) => { pb.repeat = next })
  command(app, 'PUT', `/me/player/repeat?state=${next}`)
}

export function toggleLiked(app) {
  const track = playbackOf()?.track
  const kept = recall('liked')
  if (!track || !kept || kept.uri !== track.uri || typeof kept.on !== 'boolean') return
  const on = !kept.on
  keep('liked', { uri: track.uri, on })
  if (!command(app, on ? 'PUT' : 'DELETE', `/me/library?uris=${encodeURIComponent(track.uri)}`))
    keep('liked', { uri: track.uri, on: !on })
}

export function playOn(app, device: Device) {
  keep('devices', { at: 0, list: recall('devices')?.list || [] })
  if (command(app, 'PUT', '/me/player', { device_ids: [device.id], play: true }, false)) {
    keep('lastDevice', { id: device.id, name: device.name })
    guess((pb) => { pb.device = { ...device, active: true }; pb.playing = true })
    setView('player')
  }
}

export function playList(app, list: Playlist) {
  if (command(app, 'PUT', '/me/player/play', { context_uri: list.uri })) {
    // The playlist's name and cover until Spotify says which track it is.
    guess((pb) => {
      pb.track = { id: '', uri: '', name: list.name, by: list.by, album: '', pictures: list.pictures, ms: 0, episode: false, link: '' }
      pb.progress = 0
      pb.playing = true
    })
    setView('player')
  }
}

