// The player: the cover, the words, the bar, the buttons and the volume, laid
// out for a wide, a tall or a squarish canvas, and for a round panel.
import { pictureFor } from './spotify'
import type { Playback, Upcoming } from './spotify'
import {
  cycleRepeat, note, seekDraft, seekTo, setView, setVolume, shownAt, shownPlaying, shownVolume, skip, toggleLiked,
  togglePlay, toggleShuffle, volumeDraft,
} from './remote'
import { Banner, Bar, Chip, Icon, RoundButton, clock, iconForDevice } from './ui'
import type { Sizes, Theme } from './ui'

// The album cover, decoded at the size it is drawn and kept with the
// interpreter (an ESP32 short of memory lets it go; it is fetched again).
let cover: { key: string; ref: any } | null = null
export function dropCover() {
  if (cover) frameos.releaseImage(cover.ref)
  cover = null
}

function coverFor(url: string, size: number) {
  const key = `${url}@${size}`
  if (cover && cover.key === key) return cover.ref
  if (cover) frameos.releaseImage(cover.ref)
  cover = null
  if (!url) return null
  const fetched = frameos.fetchImage(url, { keep: true, width: size, height: size })
  if (!fetched.image) return null
  cover = { key, ref: fetched.image }
  return fetched.image
}

// ---------------------------------------------------------------- the player's parts

export type Ctx = { t: Theme; z: Sizes; fast: boolean; app: any; compact?: boolean }

// The bar under the track and its times; the bar follows a finger on a fast
// screen and seeks when it lifts.
const Seek = memo(({ t, z, fast, ms, can, app }: { t: Theme; z: Sizes; fast: boolean; ms: number; can: boolean; app: any }) => {
  const draft = seekDraft.value
  const at = draft >= 0 ? draft * ms : Math.min(ms, shownAt.value)
  const fraction = ms ? at / ms : 0
  return (
    <div className="flex flex-col w-full">
      {can && ms ? (
        <Bar t={t} z={z} value={fraction} fast={fast}
          onDraft={(f) => { seekDraft.value = f }} onSet={(f) => seekTo(app, f)} />
      ) : (
        <Bar t={t} z={z} value={fraction} fast={false} onDraft={() => {}} onSet={() => {}} />
      )}
      <div className={`flex justify-between h-[${z.s(17)}px] text-[${z.s(13)}px] ${t.muted}`}>
        <span>{ms ? clock(at) : ''}</span>
        <span>{ms ? clock(ms) : ''}</span>
      </div>
    </div>
  )
})

const PlayButton = memo(({ t, z, size, can, app }: { t: Theme; z: Sizes; size: number; can: boolean; app: any }) => {
  const playing = shownPlaying.value
  return (
    <div className={`shrink-0 w-[${z.s(size)}px] h-[${z.s(size)}px] rounded-full flex items-center justify-center ${can ? t.play : t.buttonOff}`}
      onClick={can ? () => togglePlay(app) : undefined}>
      <Icon name={playing ? 'pause' : 'play'} size={z.s(size * 0.45)} />
    </div>
  )
})

// The volume: a bar to drag or tap, between - and +.
const Volume = memo(({ t, z, fast, app }: { t: Theme; z: Sizes; fast: boolean; app: any }) => {
  const draft = volumeDraft.value
  const volume = draft >= 0 ? draft : shownVolume.value
  if (volume < 0) return <div className="flex-1" />
  return (
    <div className={`flex-1 min-w-0 flex items-center gap-[${z.s(4)}px]`}>
      <RoundButton t={t} z={z} icon={volume ? 'minus' : 'mute'} size={40} onClick={() => setVolume(app, volume - 10)} />
      <Bar t={t} z={z} value={volume / 100} fast={fast} thick={t.high ? 12 : 4} grow
        onDraft={(f) => { volumeDraft.value = Math.round(f * 100) }} onSet={(f) => setVolume(app, f * 100)} />
      <RoundButton t={t} z={z} icon="plus" size={40} onClick={() => setVolume(app, volume + 10)} />
    </div>
  )
})

function Controls({ c, playback, size }: { c: Ctx; playback: Playback | null; size: number }) {
  const { t, z, app } = c
  const no = playback?.no || {}
  const has = !!playback?.track
  const repeat = playback?.repeat || 'off'
  return (
    <div className="flex items-center justify-between w-full">
      <RoundButton t={t} z={z} icon="shuffle" size={size * 0.62} on={!!playback?.shuffle} off={!has || no.shuffle}
        onClick={() => toggleShuffle(app)} />
      <RoundButton t={t} z={z} icon="prev" size={size * 0.75} off={!has || no.prev} onClick={() => skip(app, -1)} />
      <PlayButton t={t} z={z} size={size} can={playback ? !(playback.playing ? no.pause : no.resume) : true} app={app} />
      <RoundButton t={t} z={z} icon="next" size={size * 0.75} off={!has || no.next} onClick={() => skip(app, 1)} />
      <RoundButton t={t} z={z} icon="repeat" size={size * 0.62} on={repeat !== 'off'} off={!has || no.repeat}
        label={repeat === 'track' ? '1' : ''} onClick={() => cycleRepeat(app)} />
    </div>
  )
}

// The speaker it plays on (tap: the speakers) and the playlists.
function TopRow({ c, playback }: { c: Ctx; playback: Playback | null }) {
  const { t, z } = c
  const device = playback?.device
  return (
    <div className={`flex items-center gap-[${z.s(8)}px] w-full shrink-0`}>
      <Chip t={t} z={z} grow icon={device ? iconForDevice(device.type) : 'speaker'} on={!!playback?.playing}
        label={device ? device.name : 'Pick a speaker'} onClick={() => setView('devices')} />
      <Chip t={t} z={z} icon="list" label="Playlists" onClick={() => setView('playlists')} />
    </div>
  )
}

function BottomRow({ c, playback, liked }: { c: Ctx; playback: Playback | null; liked: boolean | null }) {
  const { t, z, app, fast } = c
  if (c.compact) return null
  return (
    <div className={`flex items-center gap-[${z.s(6)}px] w-full shrink-0`}>
      {liked === null ? null : (
        <RoundButton t={t} z={z} icon="heart" size={44} fill={liked} on={liked} onClick={() => toggleLiked(app)} />
      )}
      {playback?.device?.canVolume ? <Volume t={t} z={z} fast={fast} app={app} /> : <div className="flex-1" />}
    </div>
  )
}

// The cover, or a placeholder of the same size.
function Cover({ c, playback, size }: { c: Ctx; playback: Playback | null; size: number }) {
  const { t, z } = c
  const track = playback?.track
  const picture = track ? coverFor(pictureFor(track.pictures, size), size) : null
  if (picture)
    return <img src={picture} className={`shrink-0 w-[${size}px] h-[${size}px] rounded-[${z.s(8)}px] object-cover ${t.border}`} />
  return (
    <div className={`shrink-0 w-[${size}px] h-[${size}px] rounded-[${z.s(8)}px] flex items-center justify-center ${t.cover}`}>
      <Icon name={track?.episode ? 'podcast' : 'music'} size={Math.round(size * 0.4)} />
    </div>
  )
}

// The track's name (a link: on a frame, its QR code), who made it, the album.
function Words({ c, playback, big, upcoming, align }: {
  c: Ctx; playback: Playback | null; big: number; upcoming: Upcoming[]; align: string
}) {
  const { t, z } = c
  const track = playback?.track
  const name = track?.name || playback?.what || 'Nothing is playing'
  const by = track ? track.by : playback?.what ? '' : 'Pick a playlist, or play something in Spotify.'
  const title = <span className={`text-[${z.s(big)}px] font-bold leading-tight line-clamp-2 ${align}`}>{name}</span>
  const next = c.compact ? null : upcoming[0]
  return (
    <div className={`flex flex-col w-full min-w-0 gap-[${z.s(4)}px]`}>
      {track?.link ? <a href={track.link} className="flex flex-col">{title}</a> : title}
      {by ? <span className={`text-[${z.s(big * 0.62)}px] truncate ${align} ${t.muted}`}>{by}</span> : null}
      {track?.album && !c.compact ? <span className={`text-[${z.s(big * 0.5)}px] truncate ${align} ${t.faint}`}>{track.album}</span> : null}
      {next ? (
        <span className={`text-[${z.s(big * 0.46)}px] truncate ${align} ${t.faint}`}>{`Up next: ${next.name}${next.by ? ` · ${next.by}` : ''}`}</span>
      ) : null}
    </div>
  )
}

export function Problem({ c, text }: { c: Ctx; text: string }) {
  if (!text) return null
  return <Banner t={c.t} z={c.z} text={text} onClose={() => note('')} />
}

// ---------------------------------------------------------------- the player, by shape

export function wide(c: Ctx, W: number, H: number, playback: Playback | null, liked: boolean | null, upcoming: Upcoming[], problem: string) {
  const { t, z } = c
  const pad = z.s(20)
  const size = Math.round(Math.min(H - 2 * pad, W * 0.44))
  return (
    <div className={`flex items-center gap-[${pad}px] p-[${pad}px] w-full h-full ${t.page}`}>
      <Cover c={c} playback={playback} size={size} />
      <div className={`flex-1 min-w-0 h-full flex flex-col justify-between gap-[${z.s(10)}px]`}>
        <TopRow c={c} playback={playback} />
        <Problem c={c} text={problem} />
        <Words c={c} playback={playback} big={30} upcoming={upcoming} align="" />
        <div className={`flex flex-col w-full gap-[${z.s(6)}px]`}>
          <Seek t={t} z={z} fast={c.fast} ms={playback?.track?.ms || 0} can={!playback?.no?.seek} app={c.app} />
          <Controls c={c} playback={playback} size={68} />
        </div>
        <BottomRow c={c} playback={playback} liked={liked} />
      </div>
    </div>
  )
}

export function tall(c: Ctx, W: number, H: number, playback: Playback | null, liked: boolean | null, upcoming: Upcoming[], problem: string) {
  const { t, z } = c
  const pad = z.s(20)
  // The cover takes the height the rest leaves (437 px of it at 480x800).
  const size = Math.round(Math.max(z.s(120), Math.min(W - 2 * pad, H - z.s(437) - (problem ? z.s(50) : 0))))
  return (
    <div className={`flex flex-col items-center justify-between gap-[${z.s(12)}px] p-[${pad}px] w-full h-full ${t.page}`}>
      <TopRow c={c} playback={playback} />
      <Problem c={c} text={problem} />
      <Cover c={c} playback={playback} size={size} />
      <Words c={c} playback={playback} big={28} upcoming={upcoming} align="text-center" />
      <div className={`flex flex-col w-full gap-[${z.s(6)}px]`}>
        <Seek t={t} z={z} fast={c.fast} ms={playback?.track?.ms || 0} can={!playback?.no?.seek} app={c.app} />
        <Controls c={c} playback={playback} size={72} />
      </div>
      <BottomRow c={c} playback={playback} liked={liked} />
    </div>
  )
}

// Neither wide nor tall: the cover beside the words.
export function square(c: Ctx, W: number, H: number, playback: Playback | null, liked: boolean | null, upcoming: Upcoming[], problem: string) {
  const { t, z } = c
  const pad = z.s(18)
  const size = Math.round(Math.min(W * 0.36, H * 0.34))
  return (
    <div className={`flex flex-col justify-between gap-[${z.s(10)}px] p-[${pad}px] w-full h-full ${t.page}`}>
      <TopRow c={c} playback={playback} />
      <Problem c={c} text={problem} />
      <div className={`flex items-center gap-[${z.s(14)}px] w-full`}>
        <Cover c={c} playback={playback} size={size} />
        <div className="flex-1 min-w-0">
          <Words c={c} playback={playback} big={24} upcoming={[]} align="" />
        </div>
      </div>
      <div className={`flex flex-col w-full gap-[${z.s(4)}px]`}>
        <Seek t={t} z={z} fast={c.fast} ms={playback?.track?.ms || 0} can={!playback?.no?.seek} app={c.app} />
        <Controls c={c} playback={playback} size={64} />
      </div>
      <BottomRow c={c} playback={playback} liked={liked} />
    </div>
  )
}

// A round panel (only the circle inside the square shows): the cover in the
// middle, the time as a ring along the rim that a finger drags around (or a
// tap sets, on e-paper), the buttons in the arc below.
let ring = { c: 240, r: 220, band: 40 }
let ringHeld = false
const ringFraction = (e) => {
  let f = Math.atan2(e.localX - ring.c, -(e.localY - ring.c)) / (2 * Math.PI)
  return f < 0 ? f + 1 : f
}
const onRing = (e) => Math.abs(Math.hypot(e.localX - ring.c, e.localY - ring.c) - ring.r) <= ring.band
const ringPoint = (c: number, r: number, f: number) => [c + r * Math.sin(f * 2 * Math.PI), c - r * Math.cos(f * 2 * Math.PI)]

const RoundSeek = memo(({ size, r, stroke, knob, track, played, ms }: {
  size: number; r: number; stroke: number; knob: number; track: string; played: string; ms: number
}) => {
  const draft = seekDraft.value
  const at = draft >= 0 ? draft * ms : Math.min(ms, shownAt.value)
  const c = size / 2
  const f = ms ? Math.min(0.9999, Math.max(0.0005, at / ms)) : 0.0005
  const [x0, y0] = ringPoint(c, r, 0)
  const [x1, y1] = ringPoint(c, r, f)
  return (
    <svg className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={c} cy={c} r={r} stroke={track} strokeWidth={stroke} fill="none" />
      <path d={`M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 ${f > 0.5 ? 1 : 0} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}`}
        stroke={played} strokeWidth={stroke} strokeLinecap="round" fill="none" />
      <circle cx={x1.toFixed(1)} cy={y1.toFixed(1)} r={knob} fill={played} />
    </svg>
  )
})

export function round(c: Ctx, W: number, H: number, playback: Playback | null, liked: boolean | null, problem: string) {
  const { t, z, app, fast } = c
  const size = Math.min(W, H)
  const r = size / 2
  const n = (v: number) => Math.max(1, Math.round((v * r) / 240))
  const ringR = r - n(26)
  ring = { c: r, r: ringR, band: n(30) }
  const ms = playback?.track?.ms || 0
  const canSeek = !!ms && !playback?.no?.seek
  const track = playback?.track
  const coverSize = n(150)
  const box = (cy: number, h: number, w: number, extra = '') =>
    `absolute left-[${Math.round((size - w) / 2)}px] top-[${Math.round(r + cy - h / 2)}px] w-[${Math.round(w)}px] h-[${Math.round(h)}px] flex items-center justify-center ${extra}`
  const colors = t.high ? { track: '#d4d4d4', played: '#000000' } : { track: '#3a3a3a', played: '#1ed760' }
  const device = playback?.device
  const down = (e) => {
    ringHeld = canSeek && onRing(e)
    if (!ringHeld) return false
    if (fast) seekDraft.value = ringFraction(e)
  }
  const move = (e) => {
    if (!ringHeld || !e.buttons || !fast) return false
    seekDraft.value = ringFraction(e)
  }
  const up = (e) => {
    if (!ringHeld) return false
    ringHeld = false
    seekTo(app, ringFraction(e))
  }
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <div className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`} onPointerDown={down} onPointerMove={move} onPointerUp={up} />
        <RoundSeek size={size} r={ringR} stroke={t.high ? n(10) : n(6)} knob={n(9)} track={colors.track} played={colors.played} ms={ms} />
        <div className={box(-r * 0.66, n(30), r * 1.0)} onClick={() => setView('devices')}>
          <div className={`flex items-center gap-[${n(6)}px] text-[${Math.max(13, n(14))}px] ${t.muted}`}>
            <Icon name={device ? iconForDevice(device.type) : 'speaker'} size={n(16)} />
            <span className="truncate">{device ? device.name : 'Pick a speaker'}</span>
          </div>
        </div>
        <div className={box(-r * 0.28, coverSize, coverSize)}>
          <Cover c={c} playback={playback} size={coverSize} />
        </div>
        <div className={box(r * 0.17, n(30), r * 1.5)}>
          <span className={`text-[${Math.max(16, n(22))}px] font-bold truncate`}>{track?.name || playback?.what || 'Nothing is playing'}</span>
        </div>
        <div className={box(r * 0.3, n(24), r * 1.4)}>
          <span className={`text-[${Math.max(14, n(15))}px] truncate ${problem ? t.accent : t.muted}`}>{problem || (track ? track.by : '')}</span>
        </div>
        <div className={box(r * 0.52, n(64), r * 1.25)}>
          <div className="flex items-center justify-between w-full">
            <RoundButton t={t} z={z} icon="prev" size={50} off={!track || playback?.no?.prev} onClick={() => skip(app, -1)} />
            <PlayButton t={t} z={z} size={64} can={true} app={app} />
            <RoundButton t={t} z={z} icon="next" size={50} off={!track || playback?.no?.next} onClick={() => skip(app, 1)} />
          </div>
        </div>
        <div className={box(r * 0.76, n(36), r * 0.8)}>
          <div className="flex items-center justify-between w-full">
            <RoundButton t={t} z={z} icon="list" size={36} onClick={() => setView('playlists')} />
            {liked === null ? null : <RoundButton t={t} z={z} icon="heart" size={36} fill={liked} on={liked} onClick={() => toggleLiked(app)} />}
            <RoundButton t={t} z={z} icon={device ? iconForDevice(device.type) : 'speaker'} size={36} onClick={() => setView('devices')} />
          </div>
        </div>
      </div>
    </div>
  )
}

