// The two lists over the player: the speakers to play on and the playlists
// to start.
import type { Client, Playback } from './spotify'
import { devicesOf, keep, playList, playOn, playlistsOf, setView } from './remote'
import { Problem } from './player'
import type { Ctx } from './player'
import { Icon, RoundButton, iconForDevice } from './ui'

// Playlist covers: the first ones, a few fetched per render.
const THUMBS_MAX = 16
const THUMBS_PER_RENDER = 4

// Playlist covers by playlist, while the playlists show.
let thumbs: Record<string, any> = {}
// How many times get() ran in this module. A host that starts every render
// afresh (a board its control plane renders for) never gets past 1, and
// there the covers, which would be downloaded again at every render, are
// left out.
let renders = 0
export const rendered = () => ++renders

export function dropThumbs() {
  for (const uri in thumbs) frameos.releaseImage(thumbs[uri])
  thumbs = {}
}
// ---------------------------------------------------------------- the lists

function Sheet({ c, title, icon, onRefresh, children }: { c: Ctx; title: string; icon: string; onRefresh?: () => void; children: any }) {
  const { t, z } = c
  return (
    <div className={`flex flex-col w-full h-full gap-[${z.s(12)}px] p-[${z.s(18)}px] ${t.page}`}>
      <div className={`flex items-center gap-[${z.s(10)}px] shrink-0`}>
        <Icon name={icon} size={z.s(26)} />
        <span className={`flex-1 min-w-0 truncate text-[${z.s(26)}px] font-bold`}>{title}</span>
        {onRefresh ? <RoundButton t={t} z={z} icon="refresh" size={44} onClick={onRefresh} /> : null}
        <RoundButton t={t} z={z} icon="close" size={44} onClick={() => setView('player')} />
      </div>
      {children}
    </div>
  )
}

export function devicesSheet(c: Ctx, client: Client | null, playback: Playback | null, problem: string) {
  const { t, z, app } = c
  const list = devicesOf(client)
  const wanted = client?.s.speaker.toLowerCase() || ''
  const missing = wanted && !list.some((device) => device.name.toLowerCase() === wanted) ? client!.s.speaker : ''
  const activeId = playback?.device?.id || ''
  return (
    <Sheet c={c} title="Play on" icon="speaker" onRefresh={() => keep('devices', { at: 0, list })}>
      <Problem c={c} text={problem} />
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`flex flex-col gap-[${z.s(8)}px]`}>
          {list.map((device) => {
            const on = device.id === activeId || (!activeId && !!device.active)
            const sub = on
              ? (playback?.playing ? 'Playing here' : 'Paused here')
              : device.name.toLowerCase() === wanted ? 'Your speaker' : ''
            return (
              <div className={`flex items-center gap-[${z.s(12)}px] min-h-[${z.s(56)}px] px-[${z.s(14)}px] py-[${z.s(6)}px] rounded-[${z.s(12)}px] ${on ? t.rowOn : t.row}`}
                onClick={() => playOn(app, device)}>
                <Icon name={iconForDevice(device.type)} size={z.s(26)} />
                <div className="flex-1 min-w-0 flex flex-col">
                  <span className={`text-[${z.s(18)}px] font-bold truncate`}>{device.name}</span>
                  {sub ? <span className={`text-[${z.s(13)}px] truncate`}>{sub}</span> : null}
                </div>
                {on ? <Icon name="check" size={z.s(22)} /> : null}
              </div>
            )
          })}
          {missing ? (
            <div className={`flex items-center gap-[${z.s(12)}px] min-h-[${z.s(56)}px] px-[${z.s(14)}px] rounded-[${z.s(12)}px] ${t.card} ${t.faint}`}>
              <Icon name="speaker" size={z.s(26)} />
              <span className={`flex-1 min-w-0 text-[${z.s(16)}px] truncate`}>{`${missing} is not on right now`}</span>
            </div>
          ) : null}
          {list.length ? null : (
            <span className={`text-[${z.s(16)}px] ${t.muted}`}>
              No speaker is on. Open Spotify on a phone, a computer or a speaker of this account, and it shows up here.
            </span>
          )}
        </div>
      </div>
    </Sheet>
  )
}

export function playlistsSheet(c: Ctx, client: Client | null, problem: string) {
  const { t, z, app } = c
  const lists = playlistsOf(client)
  const thumb = z.s(52)
  // A few covers a render, on a screen that shows them at once and where
  // this module lives on between renders; elsewhere icons (each cover is a
  // download).
  const pictures = c.fast && renders > 1
  let fetched = 0
  if (pictures) {
    for (const list of lists.slice(0, THUMBS_MAX)) {
      if (thumbs[list.uri] !== undefined || !list.pictures.length) continue
      if (fetched >= THUMBS_PER_RENDER) {
        frameos.setNextSleep(0.2)
        break
      }
      fetched++
      thumbs[list.uri] = frameos.fetchImage(list.pictures[0].url, { keep: true, width: thumb, height: thumb }).image
    }
  }
  return (
    <Sheet c={c} title="Playlists" icon="list" onRefresh={() => keep('playlists', { at: 0, items: lists })}>
      <Problem c={c} text={problem} />
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`flex flex-col gap-[${z.s(8)}px]`}>
          {lists.map((list) => (
            <div className={`flex items-center gap-[${z.s(12)}px] p-[${z.s(6)}px] rounded-[${z.s(12)}px] ${t.row}`} onClick={() => playList(app, list)}>
              {pictures && thumbs[list.uri] ? (
                <img src={thumbs[list.uri]} className={`shrink-0 w-[${thumb}px] h-[${thumb}px] rounded-[${z.s(6)}px] object-cover`} />
              ) : (
                <div className={`shrink-0 w-[${thumb}px] h-[${thumb}px] rounded-[${z.s(6)}px] flex items-center justify-center ${t.cover}`}>
                  <Icon name="music" size={z.s(24)} />
                </div>
              )}
              <div className="flex-1 min-w-0 flex flex-col">
                <span className={`text-[${z.s(17)}px] font-bold truncate`}>{list.name}</span>
                <span className={`text-[${z.s(13)}px] truncate ${t.muted}`}>
                  {[list.by, list.count ? `${list.count} ${list.count === 1 ? 'song' : 'songs'}` : ''].filter(Boolean).join(' · ')}
                </span>
              </div>
              <Icon name="play" size={z.s(20)} />
            </div>
          ))}
          {lists.length ? null : <span className={`text-[${z.s(16)}px] ${t.muted}`}>No playlists yet.</span>}
        </div>
      </div>
    </Sheet>
  )
}

