// Talking to Spotify: the sign-in and the Web API calls the remote makes.
//
// The sign-in is the person's own Spotify app (developer.spotify.com): its
// Client ID and secret are in the scene's settings, and the address Spotify
// sends the browser to after "Agree" is pasted back into the Sign-in address
// setting. Its code is traded here for a refresh token, kept in the scene's
// private `auth` state (on the frame's disk, never shown in its settings),
// and an access token is made from it whenever the last one is about to run
// out (an hour each). Nothing goes through a FrameOS server.
//
// Every answer is cut down at once to what the remote draws (slim*), so what
// stays alive between renders is a few hundred bytes, not Spotify's JSON.

export const ACCOUNTS = 'https://accounts.spotify.com'
export const API = 'https://api.spotify.com/v1'

// What the remote asks to do: read and control playback, read and change
// Liked Songs (the heart), and list the person's playlists.
export const SCOPES = [
  'user-read-playback-state',
  'user-modify-playback-state',
  'user-read-currently-playing',
  'user-library-read',
  'user-library-modify',
  'playlist-read-private',
  'playlist-read-collaborative',
]

export const DEFAULT_REDIRECT = 'http://127.0.0.1:8888/callback'

export type Settings = { clientId: string; clientSecret: string; redirectUri: string; signIn: string; speaker: string }

export function settingsOf(app): Settings {
  const text = (key: string) => String(app.state[key] ?? '').trim()
  return {
    clientId: text('clientId'),
    clientSecret: text('clientSecret'),
    redirectUri: text('redirectUri') || DEFAULT_REDIRECT,
    signIn: text('signIn'),
    speaker: text('speaker'),
  }
}

const query = (values: Record<string, string>) =>
  Object.keys(values).map((key) => `${key}=${encodeURIComponent(values[key])}`).join('&')

// The page that asks the person to let the frame in. It holds no secret and
// no state of the frame's, so the same link works wherever it is opened: the
// frame's QR code, or the editor's preview, which opens it in a tab.
export function authorizeUrl(s: Settings) {
  return `${ACCOUNTS}/authorize?${query({
    response_type: 'code',
    client_id: s.clientId,
    scope: SCOPES.join(' '),
    redirect_uri: s.redirectUri,
  })}`
}

// The code in what was pasted: the whole address the browser ended on
// (http://127.0.0.1:8888/callback?code=...), or the code alone.
export function codeFrom(text: string) {
  const found = /[?&#]code=([^&#\s]+)/.exec(text)
  if (found) {
    try {
      return decodeURIComponent(found[1])
    } catch (e) {
      return found[1]
    }
  }
  return /^[A-Za-z0-9_-]{30,}$/.test(text) ? text : ''
}
const deniedIn = (text: string) => /[?&#]error=access_denied/.test(text)

// ---------------------------------------------------------------- the sign-in

// What the scene keeps on the frame's disk. `client` is the Client ID it was
// made with (another one signs out), `code` the last pasted code (a code
// works once: the same one pasted again, or pushed again by the control
// plane, is not traded twice), `at` when it was written.
export type Auth = {
  client?: string
  access?: string
  expires?: number
  refresh?: string
  code?: string
  error?: string
  at?: number
}

// The newest auth this interpreter wrote: frameos.setState shows in app.state
// by the next render, and a handler may come before it.
let written: Auth | null = null

export function readAuth(app): Auth {
  let saved = app.state.auth
  if (typeof saved === 'string') {
    try {
      saved = saved ? JSON.parse(saved) : {}
    } catch (e) {
      saved = {}
    }
  }
  const stored: Auth = saved && typeof saved === 'object' ? saved : {}
  return written && (written.at || 0) >= (stored.at || 0) ? written : stored
}

function writeAuth(auth: Auth) {
  auth.at = Date.now()
  written = auth
  frameos.setState('auth', auth as any)
}

type TokenReply = { ok: boolean; data?: any; error?: string; code?: string; status?: number }

function tokenRequest(s: Settings, form: Record<string, string>): TokenReply {
  const reply = frameos.httpRequest(`${ACCOUNTS}/api/token`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${btoa(`${s.clientId}:${s.clientSecret}`)}`,
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body: query(form),
    timeoutMs: 10000,
  })
  if (!reply.status) return { ok: false, error: `Could not reach Spotify: ${reply.error || 'no answer'}` }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status === 200 && data && data.access_token) return { ok: true, data }
  const code = String(data?.error || '')
  const said = String(data?.error_description || '')
  return { ok: false, code, status: reply.status, error: tokenProblem(code, said, reply.status) }
}

// What a refusal at the token endpoint means to a person.
function tokenProblem(code: string, said: string, status: number) {
  if (code === 'invalid_client')
    return 'Spotify does not know this Client ID and Client secret: copy both again from your app on developer.spotify.com.'
  if (code === 'invalid_grant' && /redirect/i.test(said))
    return "The Redirect URI in this scene's settings is not the one in your Spotify app. Make them the same and sign in again."
  if (code === 'invalid_grant' && /refresh/i.test(said))
    return 'Spotify ended this sign-in (it was revoked, or the app was reset). Sign in again.'
  if (code === 'invalid_grant')
    return 'That sign-in address was used already or is too old (it works once, for a few minutes). Sign in again and paste the new one.'
  if (status === 429) return 'Spotify asks to wait a little before the next sign-in.'
  return `Spotify refused the sign-in: ${said || code || `HTTP ${status}`}`
}

const fromToken = (s: Settings, data: any, refresh: string, code: string): Auth => ({
  client: s.clientId,
  access: String(data.access_token),
  expires: Date.now() + Math.max(60, Number(data.expires_in) || 3600) * 1000,
  refresh: String(data.refresh_token || refresh),
  code,
})

export type Session = {
  token: string
  // Signed in, perhaps with a problem for the moment: no network. Otherwise the
  // sign-in screen shows, with the problem when there is one.
  signedIn: boolean
  problem: string
}

// Trades a pasted address for a sign-in, and an old access token for a new
// one. `force` makes a new one even when the last has time left (after a 401).
export function session(app, s: Settings, force = false): Session {
  let auth = readAuth(app)
  if (auth.client && auth.client !== s.clientId) auth = { code: auth.code }

  const pasted = s.signIn
  const code = pasted ? codeFrom(pasted) : ''
  if (pasted && (!code || code !== auth.code)) {
    if (code) {
      const reply = tokenRequest(s, { grant_type: 'authorization_code', code, redirect_uri: s.redirectUri })
      if (reply.ok) auth = fromToken(s, reply.data, '', code)
      // A failed new sign-in keeps one that works.
      else if (reply.code || reply.status) auth = { ...auth, code, error: reply.error }
      else return { token: '', signedIn: !!auth.refresh, problem: reply.error || '' }
    } else {
      auth = {
        ...auth,
        error: deniedIn(pasted)
          ? 'You did not let the frame in on Spotify\'s page. Sign in again and press "Agree".'
          : 'The Sign-in address has no code in it: paste the whole address the browser ended on after "Agree".',
      }
    }
    writeAuth(auth)
    frameos.setState('signIn', '')
  }

  if (!auth.refresh) return { token: '', signedIn: false, problem: auth.error || '' }
  if (!force && auth.access && (auth.expires || 0) > Date.now() + 60000)
    return { token: auth.access, signedIn: true, problem: '' }

  const reply = tokenRequest(s, { grant_type: 'refresh_token', refresh_token: auth.refresh })
  if (reply.ok) {
    auth = fromToken(s, reply.data, auth.refresh, auth.code || '')
    writeAuth(auth)
    return { token: auth.access!, signedIn: true, problem: '' }
  }
  if (reply.code === 'invalid_grant' || reply.code === 'invalid_client') {
    writeAuth({ client: s.clientId, code: auth.code, error: reply.error })
    return { token: '', signedIn: false, problem: reply.error || '' }
  }
  return { token: '', signedIn: true, problem: reply.error || 'Could not reach Spotify' }
}

// ---------------------------------------------------------------- the Web API

export type Reply = { status: number; data?: any; error?: string; reason?: string }

// Spotify's "slow down": no call until then (frameos.remember, so it holds
// across renders and on a board that starts each render afresh).
const waitUntil = () => Number(frameos.recall('wait') || 0)

export type Client = { app: any; s: Settings; token: string }

export function call(client: Client, method: string, path: string, body?: any, retried = false): Reply {
  const wait = waitUntil()
  if (wait > Date.now())
    return { status: 429, error: `Spotify asked the frame to slow down: it asks again in ${Math.ceil((wait - Date.now()) / 1000)} s.` }
  const reply = frameos.httpRequest(API + path, {
    method,
    headers: {
      Authorization: `Bearer ${client.token}`,
      Accept: 'application/json',
      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
    },
    // Spotify wants a body (even an empty one) with every PUT and POST.
    body: body !== undefined ? JSON.stringify(body) : method === 'PUT' || method === 'POST' ? '' : undefined,
    timeoutMs: 8000,
  })
  if (!reply.status) return { status: 0, error: `Could not reach Spotify: ${reply.error || 'no answer'}` }
  if (reply.status === 401 && !retried) {
    const again = session(client.app, client.s, true)
    if (!again.token) return { status: 401, error: again.problem || 'Signed out of Spotify' }
    client.token = again.token
    return call(client, method, path, body, true)
  }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status === 429) {
    const seconds = Math.min(600, Math.max(5, Number(reply.headers?.['retry-after']) || 30))
    frameos.remember('wait', Date.now() + seconds * 1000)
    return { status: 429, error: `Spotify asked the frame to slow down: it asks again in ${seconds} s.` }
  }
  if (reply.status >= 400) {
    const error = data?.error
    const message = typeof error === 'object' ? String(error?.message || '') : String(error || '')
    const reason = typeof error === 'object' ? String(error?.reason || '') : ''
    return { status: reply.status, error: commandProblem(reply.status, message, reason), reason }
  }
  return { status: reply.status, data }
}

function commandProblem(status: number, message: string, reason: string) {
  if (reason === 'NO_ACTIVE_DEVICE') return 'Nothing is playing anywhere: pick a speaker first.'
  if (reason === 'PREMIUM_REQUIRED') return 'Controlling playback needs Spotify Premium.'
  if (status === 403 && /user may not be registered|not registered/i.test(message))
    return "Spotify does not let this account use your app yet: add it under User Management in your app's settings."
  if (status === 403 && /restriction/i.test(message)) return 'Spotify does not allow that right now.'
  return `Spotify answered: ${message || `HTTP ${status}`}`
}

// ---------------------------------------------------------------- what the remote keeps

export type Picture = { url: string; w: number }
export type Track = {
  id: string
  uri: string
  name: string
  by: string
  album: string
  pictures: Picture[]
  ms: number
  episode: boolean
  link: string
}
export type Device = { id: string; name: string; type: string; volume: number | null; canVolume: boolean; active?: boolean }
export type Playback = {
  // When it was read (Date.now()), and where the track was then.
  at: number
  progress: number
  playing: boolean
  track: Track | null
  // An ad, a podcast Spotify cannot describe, or nothing at all.
  what: string
  device: Device | null
  shuffle: boolean
  repeat: string
  // What Spotify says cannot be done at the moment: no skipping in an ad, say.
  no: Record<string, boolean>
}

// Pictures smallest first, three at most (Spotify sends 64, 300 and 640 px).
function slimPictures(images: any): Picture[] {
  if (!Array.isArray(images)) return []
  return images
    .filter((image) => image && image.url)
    .map((image) => ({ url: String(image.url), w: Number(image.width) || 0 }))
    .sort((a, b) => a.w - b.w)
    .slice(0, 3)
}

// The smallest picture at least `size` pixels wide, else the largest.
export function pictureFor(pictures: Picture[], size: number) {
  for (const picture of pictures) if (picture.w >= size || !picture.w) return picture.url
  return pictures.length ? pictures[pictures.length - 1].url : ''
}

export function slimDevice(device: any): Device | null {
  if (!device) return null
  return {
    id: String(device.id || ''),
    name: String(device.name || 'A speaker'),
    type: String(device.type || ''),
    volume: typeof device.volume_percent === 'number' ? device.volume_percent : null,
    canVolume: device.supports_volume !== false,
    active: !!device.is_active,
  }
}

function slimTrack(item: any): Track | null {
  if (!item || !item.name) return null
  const episode = item.type === 'episode'
  const artists = Array.isArray(item.artists) ? item.artists.map((artist) => artist?.name).filter(Boolean) : []
  return {
    id: String(item.id || ''),
    uri: String(item.uri || ''),
    name: String(item.name),
    by: episode ? String(item.show?.name || '') : artists.join(', '),
    album: episode ? '' : String(item.album?.name || ''),
    pictures: slimPictures(episode ? item.images || item.show?.images : item.album?.images),
    ms: Number(item.duration_ms) || 0,
    episode,
    link: String(item.external_urls?.spotify || ''),
  }
}

export function slimPlayback(data: any): Playback | null {
  if (!data) return null
  // GET /me/player says what cannot be done under actions.disallows (the
  // reference documents the keys on actions itself): true means "not now".
  const actions = data.actions || {}
  const disallows = actions.disallows || actions
  const type = String(data.currently_playing_type || '')
  return {
    at: Date.now(),
    progress: Number(data.progress_ms) || 0,
    playing: !!data.is_playing,
    track: slimTrack(data.item),
    what: type === 'ad' ? 'An ad' : type === 'episode' ? 'A podcast' : '',
    device: slimDevice(data.device),
    shuffle: !!data.shuffle_state,
    repeat: String(data.repeat_state || 'off'),
    no: {
      pause: !!disallows.pausing,
      resume: !!disallows.resuming,
      next: !!disallows.skipping_next,
      prev: !!disallows.skipping_prev,
      seek: !!disallows.seeking,
      shuffle: !!disallows.toggling_shuffle,
      repeat: !!(disallows.toggling_repeat_context && disallows.toggling_repeat_track),
    },
  }
}

// Where the track is now: where it was when read, plus the time since while
// it plays.
export function positionOf(playback: Playback, now: number) {
  const ms = playback.progress + (playback.playing ? now - playback.at : 0)
  return playback.track?.ms ? Math.max(0, Math.min(playback.track.ms, ms)) : Math.max(0, ms)
}

export type Upcoming = { name: string; by: string }
export function slimQueue(data: any): Upcoming[] {
  const items = Array.isArray(data?.queue) ? data.queue : []
  return items.slice(0, 5).map(slimTrack).filter(Boolean).map((track) => ({ name: track!.name, by: track!.by }))
}

export type Playlist = { name: string; uri: string; by: string; count: number; pictures: Picture[] }
export function slimPlaylists(data: any): Playlist[] {
  const items = Array.isArray(data?.items) ? data.items : []
  return items
    .filter((item) => item && item.uri)
    .slice(0, 50)
    .map((item) => ({
      name: String(item.name || 'A playlist'),
      uri: String(item.uri),
      by: String(item.owner?.display_name || ''),
      // `items` since February 2026, `tracks` before.
      count: Number(item.items?.total ?? item.tracks?.total) || 0,
      pictures: slimPictures(item.images).slice(0, 1),
    }))
}

