// The parts of the remote that know nothing of Spotify: the two looks, sizes
// worked out from the canvas, icons, buttons, sliders and the setup screens.
// app.tsx decides what shows; this file only draws.

// ---------------------------------------------------------------- looks

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Near-black with one green accent for what is on, or black on white with
// borders and black fills for what is on: no greys to dither on e-paper.
const THEMES = {
  color: {
    high: false,
    page: 'bg-[#121212] text-white',
    muted: 'text-[#b3b3b3]',
    faint: 'text-[#7a7a7a]',
    accent: 'text-[#1ed760]',
    card: 'bg-[#1f1f1f]',
    row: 'bg-[#1f1f1f] active:bg-[#2a2a2a]',
    rowOn: 'bg-[#1f3a29] active:bg-[#24452f]',
    cover: 'bg-[#2a2a2a] text-[#7a7a7a]',
    button: 'text-white active:bg-white/10',
    buttonOff: 'text-[#5c5c5c]',
    chip: 'bg-[#2a2a2a] text-white active:bg-[#3a3a3a]',
    chipOn: 'bg-[#1ed760] text-black active:bg-[#3be477]',
    play: 'bg-white text-black active:bg-[#d4d4d4]',
    primary: 'bg-[#1ed760] text-black active:bg-[#3be477]',
    track: 'bg-white/25',
    fill: 'bg-white',
    knob: 'bg-white',
    banner: 'bg-[#4a1d1d] text-[#ffd6d6]',
    code: 'bg-[#2a2a2a] text-[#1ed760]',
    step: 'bg-[#1ed760] text-black',
    border: '',
  },
  high: {
    high: true,
    page: 'bg-white text-black',
    muted: 'text-black',
    faint: 'text-black',
    accent: 'text-black',
    card: 'bg-white border-2 border-black',
    row: 'bg-white border-2 border-black',
    rowOn: 'bg-black text-white border-2 border-black',
    cover: 'bg-white text-black border-2 border-black',
    button: 'text-black',
    buttonOff: 'text-black opacity-40',
    chip: 'bg-white text-black border-2 border-black',
    chipOn: 'bg-black text-white border-2 border-black',
    play: 'bg-black text-white',
    primary: 'bg-black text-white',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    knob: 'bg-black',
    banner: 'bg-black text-white',
    code: 'bg-white text-black border-2 border-black',
    step: 'bg-black text-white',
    border: 'border-2 border-black',
  },
}
export type Theme = typeof THEMES.color
export const themeOf = (app): Theme => (highContrast(app) ? THEMES.high : THEMES.color)

// Every length comes from the canvas: 1 at the size a layout was drawn for
// (800x480 wide, 480x800 tall, 480x480 square), more on a bigger panel.
// s(16) is what 16 px is on this frame.
export function sizesOf(W: number, H: number, baseW = 480, baseH = 480) {
  const k = Math.max(0.6, Math.min(2.5, Math.min(W / baseW, H / baseH)))
  const s = (px: number) => Math.max(1, Math.round(px * k))
  return { W, H, k, s }
}
export type Sizes = ReturnType<typeof sizesOf>

// ---------------------------------------------------------------- icons

// Icons in a 24x24 box, drawn in the text color: lines, except the ones in
// FILLED. Speakers by the type Spotify gives them.
const PATHS: Record<string, string> = {
  play: 'M7 4l13 8-13 8z',
  pause: 'M6 4h4v16H6zM14 4h4v16h-4z',
  next: 'M5 4l10 8-10 8zM17 4h2v16h-2z',
  prev: 'M19 20L9 12l10-8zM5 4h2v16H5z',
  shuffle: 'M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5',
  repeat: 'M17 1l4 4-4 4M3 11V9a4 4 0 0 1 4-4h14M7 23l-4-4 4-4M21 13v2a4 4 0 0 1-4 4H3',
  heart: 'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1.1 7.8 7.8 7.8-7.8 1-1.1a5.5 5.5 0 0 0 0-7.8z',
  volume: 'M11 5L6 9H2v6h4l5 4zM15.5 8.5a5 5 0 0 1 0 7M19 5a10 10 0 0 1 0 14',
  mute: 'M11 5L6 9H2v6h4l5 4zM22 9l-6 6M16 9l6 6',
  minus: 'M5 12h14',
  plus: 'M12 5v14M5 12h14',
  list: 'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
  close: 'M18 6L6 18M6 6l12 12',
  music: 'M9 18V5l12-2v13M9 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0zM21 16a3 3 0 1 1-6 0 3 3 0 0 1 6 0z',
  podcast: 'M12 11a1 1 0 1 0 0 2 1 1 0 0 0 0-2zM12 15v6M8.5 15.5a5 5 0 1 1 7 0M5.6 18.4a9 9 0 1 1 12.8 0',
  alert: 'M12 3l10 18H2zM12 10v4M12 17v.01',
  refresh: 'M21 12a9 9 0 1 1-2.6-6.4L21 8M21 3v5h-5',
  check: 'M5 12l5 5L20 7',
  key: 'M15 7a4 4 0 1 0-3.9 4.9L4 19v2h3v-2h2v-2h2l1.1-1.1A4 4 0 0 0 15 7zM15.5 7.5h.01',
  link: 'M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7',
  // Speakers
  speaker: 'M6 2h12v20H6zM12 6h.01M12 11a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7z',
  computer: 'M4 5h16v11H4zM2 19h20',
  smartphone: 'M7 2h10v20H7zM11 18h2',
  tablet: 'M5 3h14v18H5zM11 17h2',
  tv: 'M3 7h18v13H3zM17 2l-5 5-5-5',
  cast: 'M2 16.1A5 5 0 0 1 5.9 20M2 12.05A9 9 0 0 1 9.95 20M2 8V6h20v14h-8M2 20h.01',
  car: 'M5 17h14v-5l-2-5H7l-2 5zM5 17v2M19 17v2M8 14h.01M16 14h.01',
  game: 'M6 12h4M8 10v4M15 13h.01M18 11h.01M2 9a4 4 0 0 1 4-4h12a4 4 0 0 1 4 4v6a4 4 0 0 1-7.2 2.4L14 16h-4l-.8 1.4A4 4 0 0 1 2 15z',
  frame: 'M3 4h18v14H3zM8 21h8M12 18v3',
}
const FILLED: Record<string, boolean> = { play: true, pause: true, next: true, prev: true }

export const iconForDevice = (type: string) =>
  ({
    Computer: 'computer', Smartphone: 'smartphone', Tablet: 'tablet', TV: 'tv', CastVideo: 'cast', CastAudio: 'cast',
    Automobile: 'car', GameConsole: 'game', STB: 'tv', AVR: 'speaker', AudioDongle: 'speaker', Speaker: 'speaker',
  } as Record<string, string>)[type] || 'speaker'

export const Icon = ({ name, size, fill }: { name: string; size: number; fill?: boolean }) => {
  const filled = FILLED[name]
  return (
    <svg className={`w-[${size}px] h-[${size}px] shrink-0`} viewBox="0 0 24 24"
      fill={filled || fill ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth={filled ? 0 : 2}
      strokeLinecap="round" strokeLinejoin="round">
      <path d={PATHS[name] || PATHS.music} />
    </svg>
  )
}

// ---------------------------------------------------------------- helpers

export const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, value))

// 3:07, or 1:02:44 for a long podcast.
export function clock(ms: number) {
  const seconds = Math.max(0, Math.floor(ms / 1000))
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  const s = String(seconds % 60).padStart(2, '0')
  return h ? `${h}:${String(m).padStart(2, '0')}:${s}` : `${m}:${s}`
}

// ---------------------------------------------------------------- parts

// A round button with an icon: the controls under the track.
export function RoundButton({ t, z, icon, size, on, off, fill, label, onClick }: {
  t: Theme; z: Sizes; icon: string; size: number; on?: boolean; off?: boolean; fill?: boolean; label?: string; onClick?: () => void
}) {
  const look = off ? t.buttonOff : on ? t.accent : t.button
  return (
    <div className={`relative shrink-0 w-[${z.s(size)}px] h-[${z.s(size)}px] rounded-full flex items-center justify-center ${look}`}
      onClick={off ? undefined : onClick}>
      <Icon name={icon} size={z.s(size * 0.5)} fill={fill} />
      {label ? (
        <span className={`absolute right-[${z.s(size * 0.12)}px] top-[${z.s(size * 0.08)}px] text-[${z.s(size * 0.24)}px] font-bold`}>{label}</span>
      ) : null}
    </div>
  )
}

// A pill with an icon and words: the speaker the music plays on, Playlists.
export function Chip({ t, z, icon, label, on, onClick, grow }: {
  t: Theme; z: Sizes; icon: string; label: string; on?: boolean; onClick?: () => void; grow?: boolean
}) {
  return (
    <div className={`${grow ? 'flex-1' : 'shrink-0'} min-w-0 h-[${z.s(38)}px] px-[${z.s(14)}px] rounded-full flex items-center gap-[${z.s(8)}px] text-[${z.s(15)}px] ${on ? t.chipOn : t.chip}`}
      onClick={onClick}>
      <Icon name={icon} size={z.s(18)} />
      <span className="truncate">{label}</span>
    </div>
  )
}

// A bar to drag (on a fast panel: it follows the finger, and the value is
// sent when it lifts) or to tap (on e-paper: one refresh, one request).
// `value` is from 0 to 1.
// `grow`: in a row beside other things, else as wide as its parent.
export function Bar({ t, z, value, fast, thick, grow, onDraft, onSet }: {
  t: Theme; z: Sizes; value: number; fast: boolean; thick?: number; grow?: boolean
  onDraft: (fraction: number) => void; onSet: (fraction: number) => void
}) {
  const at = (e) => clamp(e.localX / Math.max(1, e.width), 0, 1)
  const h = z.s(thick || (t.high ? 14 : 6))
  const knob = z.s(t.high ? 18 : 14)
  const percent = Math.round(clamp(value, 0, 1) * 1000) / 10
  return (
    <div className={`flex items-center h-[${z.s(30)}px] ${grow ? 'flex-1 min-w-0' : 'w-full'}`}
      onPointerDown={fast ? (e) => onDraft(at(e)) : undefined}
      onPointerMove={fast ? (e) => { if (e.buttons) onDraft(at(e)) } : undefined}
      onPointerUp={fast ? (e) => onSet(at(e)) : undefined}
      onClick={fast ? undefined : (e) => onSet(at(e))}>
      <div className={`flex-1 h-[${h}px] rounded-full ${t.track}`}>
        <div className={`flex items-center justify-end h-full w-[${percent}%] min-w-[${h}px] rounded-full ${t.fill}`}>
          {fast ? <div className={`shrink-0 w-[${knob}px] h-[${knob}px] -mr-[${Math.round(knob / 2)}px] rounded-full ${t.knob}`} /> : null}
        </div>
      </div>
    </div>
  )
}

// A screen that says what to do, step by step, with a button at the bottom.
// `tight`: a short screen (a 4.2" e-paper, a 2.8" LCD, a watch), where less
// room between the parts keeps every step on the screen. `round`: a round
// panel's whole canvas, where the title sits in the arc at the top, the
// steps scroll in the middle of the circle with the note after them, and the
// button stays in the arc at the bottom.
export type Step = { head: string; text: string; code?: string }
export function SetupScreen({ t, z, icon, title, intro, steps, problem, action, note, tight, round }: {
  t: Theme; z: Sizes; icon: string; title: string; intro: string; steps: Step[]; problem?: string; action?: any; note?: string
  tight?: boolean; round?: { W: number; H: number }
}) {
  const g = (px: number) => z.s(tight ? px * 0.55 : px)
  const list = (
    <div className={`flex flex-col gap-[${g(10)}px]`}>
      {steps.map((step, index) => (
        <div className={`flex gap-[${z.s(12)}px] rounded-[${z.s(14)}px] px-[${z.s(12)}px] py-[${g(10)}px] ${t.card}`}>
          <div className={`w-[${z.s(30)}px] h-[${z.s(30)}px] shrink-0 rounded-full flex items-center justify-center text-[${z.s(16)}px] font-bold ${t.step}`}>
            {index + 1}
          </div>
          <div className={`flex-1 min-w-0 flex flex-col gap-[${tight ? 1 : 4}px]`}>
            <span className={`text-[${z.s(17)}px] font-bold`}>{step.head}</span>
            <span className={`text-[${z.s(14)}px] ${t.muted}`}>{step.text}</span>
            {step.code ? (
              <span className={`self-start rounded-[8px] px-[${z.s(8)}px] ${tight ? '' : 'py-[2px] '}font-mono text-[${z.s(13)}px] ${t.code}`}>{step.code}</span>
            ) : null}
          </div>
        </div>
      ))}
    </div>
  )
  if (round) {
    const { W, H } = round
    const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    // The icon at the top of the circle, the title under it where the
    // circle is wide enough for it.
    const iconTop = Math.round(R * 0.93)
    const iconSize = z.s(38)
    const titleTop = iconTop - iconSize - z.s(4)
    const titleH = Math.round(z.s(22) * 1.3)
    const boxTop = titleTop - titleH - z.s(8)
    const actionH = action ? z.s(52) : 0
    const boxBottom = action ? Math.round(R * 0.38) : Math.round(R * 0.7)
    const boxW = Math.min(chord(boxTop), chord(boxBottom))
    const titleW = chord(titleTop)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${Math.round(cx - iconSize / 2)}px] top-[${Math.round(cy - iconTop)}px] w-[${iconSize}px] h-[${iconSize}px] rounded-full flex items-center justify-center ${t.step}`}>
          <Icon name={icon} size={z.s(21)} />
        </div>
        <div className={`absolute left-[${Math.round(cx - titleW / 2)}px] top-[${Math.round(cy - titleTop)}px] w-[${titleW}px] flex justify-center`}>
          <span className={`text-[${z.s(22)}px] font-bold leading-tight truncate`}>{title}</span>
        </div>
        <div className={`absolute left-[${Math.round(cx - boxW / 2)}px] top-[${Math.round(cy - boxTop)}px] w-[${boxW}px] h-[${boxTop + boxBottom}px] overflow-y-auto`}>
          <div className={`flex flex-col gap-[${z.s(10)}px]`}>
            {problem ? <Banner t={t} z={z} text={problem} /> : <span className={`text-[${z.s(15)}px] text-center ${t.muted}`}>{intro}</span>}
            {list}
            {note ? <span className={`text-[${z.s(13)}px] text-center ${t.muted}`}>{note}</span> : null}
          </div>
        </div>
        {action ? (
          <div className={`absolute left-[${Math.round(cx - chord(boxBottom + z.s(8) + actionH) / 2)}px] top-[${Math.round(cy + boxBottom + z.s(8))}px] w-[${chord(boxBottom + z.s(8) + actionH)}px] h-[${actionH}px] flex justify-center`}>
            {action}
          </div>
        ) : null}
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full gap-[${g(12)}px] p-[${g(20)}px] ${t.page}`}>
      <div className={`flex items-center gap-[${z.s(12)}px]`}>
        <div className={`w-[${z.s(48)}px] h-[${z.s(48)}px] shrink-0 rounded-full flex items-center justify-center ${t.step}`}>
          <Icon name={icon} size={z.s(26)} />
        </div>
        <div className="flex-1 min-w-0 flex flex-col">
          <span className={`text-[${z.s(26)}px] font-bold leading-tight`}>{title}</span>
          {problem ? null : <span className={`text-[${z.s(15)}px] ${t.muted}`}>{intro}</span>}
        </div>
      </div>
      {problem ? <Banner t={t} z={z} text={problem} /> : null}
      <div className="flex-1 min-h-0 overflow-y-auto">{list}</div>
      {action || null}
      {note ? <span className={`text-[${z.s(13)}px] ${t.muted}`}>{note}</span> : null}
    </div>
  )
}

export function Banner({ t, z, text, onClose }: { t: Theme; z: Sizes; text: string; onClose?: () => void }) {
  return (
    <div className={`flex items-center shrink-0 gap-[${z.s(10)}px] rounded-[${z.s(12)}px] px-[${z.s(12)}px] py-[${z.s(8)}px] ${t.banner}`}
      onClick={onClose}>
      <Icon name="alert" size={z.s(20)} />
      <span className={`flex-1 text-[${z.s(14)}px] line-clamp-2`}>{text}</span>
      {onClose ? <Icon name="close" size={z.s(18)} /> : null}
    </div>
  )
}
